// bf16(32x32) tiles in the dead v-stage region, and the MMA warp rebuilds the
// gate-scaled fp32 state accumulator on the tensor pipe (one kda_mma_rebuild
// per 32-col block: A = Sinp TMEM slice, B = diag(gt) tile) right before the
// ft accumulation. This removes the per-chunk fp32 ld->mul->st rescale and
// its pre-UMMA-2 handoff from the serial chain. Carried-state numerics are
// bf16-quantized per chunk (validated by the R22 probe: max_abs_err unchanged
// at 4.88e-04 on all 14 fixed-benchmark shapes).
// K=32, N=32, D fp32, A from TMEM, B = standalone diag tile (inv-family
// descriptor: dhi 0xC0004010, 2048B tile, desc step +64 per K16; M=64 idesc).
__device__ __forceinline__ void kda_mma_rebuild(int d_tmem, int b_lo, int a_tmem, int accum0) {
    asm volatile(
        "{\n\t"
        ".reg .pred leader, p0, p1;\n\t"
        ".reg .b32 dhi, blo, id;\n\t"
        ".reg .b64 db;\n\t"
        "elect.sync _|leader, 0xFFFFFFFF;\n\t"
        "setp.ne.b32 p0, %3, 0;\n\t"
        "setp.ne.b32 p1, 1, 0;\n\t"
        "mov.b32 dhi, 0xC0004010;\n\t"
        "mov.b32 id, 67634320;\n\t"
        "mov.b32 blo, %1;\n\t"
        "mov.b64 db, {blo, dhi};\n\t"
        "@leader tcgen05.mma.cta_group::1.kind::f16 [%0], [%2], db, id, p0;\n\t"
        "add.u32 blo, blo, 64;\n\t"
