        "@leader tcgen05.mma.cta_group::1.kind::f16 [%0], [%2 + 8], db, id, p1;\n\t"
        "}\n"
        :: "r"(d_tmem), "r"(b_lo), "r"(a_tmem), "r"(accum0));
}
