// Pair-state pass: ld S fp32 (one 64-col half), pack Sinp_a (pre-decay),
// scale by gt_a (E_a), pack Sinp_b, scale by gt_b (E_b), store fp32 back.
// gt_b == NULL => single-chunk variant (skip Sinp_b pack and E_b scale).
static __device__ __forceinline__ void kda_pm_state_half(
    int taddr_row, int half, int lane_quad,
    const float* gt_a, const float* gt_b, int sinp_a_off, int sinp_b_off) {
    int state_addr = taddr_row + (unsigned int)(half * 64);
    float tmp[32];
    KDA_TLD32(tmp, state_addr);
    KDA_TPACK16_ST(taddr_row + (unsigned int)sinp_a_off + (unsigned int)(half * 32), tmp);
    #pragma unroll
    for (int g = 0; g < 8; g++) {
        int cp = half * 64 + g * 8 + lane_quad * 2;
        float s0 = gt_a[cp];
        float s1 = gt_a[cp + 1];
        const int rb = g * 4;
        tmp[rb] = tmp[rb] * s0;
        tmp[rb + 1] = tmp[rb + 1] * s1;
        tmp[rb + 2] = tmp[rb + 2] * s0;
        tmp[rb + 3] = tmp[rb + 3] * s1;
    }
    if (gt_b != 0) {
        KDA_TPACK16_ST(taddr_row + (unsigned int)sinp_b_off + (unsigned int)(half * 32), tmp);
        #pragma unroll
        for (int g = 0; g < 8; g++) {
            int cp = half * 64 + g * 8 + lane_quad * 2;
            float s0 = gt_b[cp];
            float s1 = gt_b[cp + 1];
            const int rb = g * 4;
            tmp[rb] = tmp[rb] * s0;
            tmp[rb + 1] = tmp[rb + 1] * s1;
            tmp[rb + 2] = tmp[rb + 2] * s0;
            tmp[rb + 3] = tmp[rb + 3] * s1;
        }
    }
    KDA_TST32(state_addr, tmp);
}

